{"path": "transpose.py", "content": "def transpose(text):
    if not text:
        return ""
    lines = text.split("\n")
    # Pad each row on the right to the length of the longest row below it,
    # so shorter rows above longer ones get spaces (left-padding in output).
    width = 0
    for i in range(len(lines) - 1, -1, -1):
        width = max(width, len(lines[i]))
        lines[i] = lines[i].ljust(width)
    max_len = len(lines[0])
    return "\n".join(
        "".join(line[j] for line in lines if j < len(line))
        for j in range(max_len)
    )
"}
